[Console]::OutputEncoding=New-Object System.Text.UTF8Encoding($false)
foreach($log in @('Microsoft-Windows-Kernel-PnP/Configuration','Microsoft-Windows-DriverFrameworks-UserMode/Operational','System')) {
 try { $info=Get-WinEvent -ListLog $log -ErrorAction Stop; $last=Get-WinEvent -LogName $log -MaxEvents 3 -ErrorAction Stop;[ordered]@{log=$log;enabled=$info.IsEnabled;count=$info.RecordCount;last=@($last | Select-Object TimeCreated,Id,ProviderName,Message)} | ConvertTo-Json -Depth 4 -Compress }
 catch { [ordered]@{log=$log;error=$_.Exception.Message} | ConvertTo-Json -Compress }
}
